keyframes.moveHorizontal:
@keyframes moveHorizontal { 
  0% { transform: translate(-50%) translateY(-10%); }
  50% { transform: translate(50%) translateY(10%); }
  100% { transform: translate(-50%) translateY(-10%); }
}

keyframes.moveInCircle:
@keyframes moveInCircle { 
  0% { transform: rotate(0deg); }
  50% { transform: rotate(180deg); }
  100% { transform: rotate(360deg); }
}

keyframes.moveVertical:
@keyframes moveVertical { 
  0% { transform: translateY(-50%); }
  50% { transform: translateY(50%); }
  100% { transform: translateY(-50%); }
}

keyframes.bannerSheen:
@keyframes bannerSheen { 
  0% { transform: translate(-140%) skew(-18deg); }
  55% { transform: translate(240%) skew(-18deg); }
  100% { transform: translate(240%) skew(-18deg); }
}

inlineStyles:
.main-container { width: 100%; max-width: 1440px; padding: 0 96px; }
.content-container { width: 100%; max-width: 1248px; }
@media (max-width: 1024px) { .main-container { padding: 0 40px; } }
@media (max-width: 640px) { .main-container { padding: 0 20px; } }
